{"files": {"render.mjs": "export function renderBoard(puzzle, pegs, selected, targets) {
  const board = document.getElementById('board');
  board.innerHTML = '';
  const cells = puzzle.cells;
  const pegSet = new Set(pegs);
  const goalSet = new Set(puzzle.goal);
  const targetSet = new Set(targets);
  const minX = Math.min(...cells.map(c => c.split(',')[0]));
  const maxX = Math.max(...cells.map(c => c.split(',')[0]));
  const minY = Math.min(...cells.map(c => c.split(',')[1]));
  const maxY = Math.max(...cells.map(c => c.split(',')[1]));
  const cols = maxX - minX + 1;
  const rows = maxY - minY + 1;
  board.style.gridTemplateColumns = `repeat(${cols}, 1fr)`;
  board.style.gridTemplateRows = `repeat(${rows}, 1fr)`;
  for (const cell of cells) {
    const [x, y] = cell.split(',').map(Number);
    const btn = document.createElement('button');
    btn.textContent = '';
    btn.setAttribute('data-cell', cell);
    btn.style.gridColumn = x - minX + 1;
    btn.style.gridRow = y - minY + 1;
    const occupied = pegSet.has(cell);
    btn.setAttribute('data-occupied', occupied);
    btn.classList.toggle('peg', occupied);
    btn.classList.toggle('goal', goalSet.has(cell));
    btn.classList.toggle('selected', selected === cell);
    btn.classList.toggle('target', targetSet.has(cell));
    btn.setAttribute('aria-label', `${cell}, ${occupied ? 'occupied' : 'empty'}`);
    board.appendChild(btn);
  }
}"}}
